def hpalindrome_rows(grid):
    """Each row as reversed(row) + row: a horizontal palindrome of double width."""
    return [list(reversed(row)) + row for row in grid]

def vsandwich3(grid):
    """Vertical-mirror + grid + vertical-mirror: grid stacked between two flipped copies."""
    return grid[::-1] + grid + grid[::-1]

from lib import hpalindrome_rows, vsandwich3

def transform(grid):
    """Rows as horizontal palindromes, stacked as vertical-mirror, original, vertical-mirror."""
    return vsandwich3(hpalindrome_rows(grid))

